INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Datenherkunft immer eindeutig nachvollziehbar?', 2, '[{"text": "Nein", "correct": true, "because": "Kann durch Manipulation unklar sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Nachverfolgung der Datenherkunft?', 3, '[{"text": "Datenintegrität sichern", "correct": true, "because": "Vertrauen in Daten stärken"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein Netzwerkziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, die Datenherkunft zu bestimmen?', 5, '[{"text": "Metadaten", "correct": true, "because": "Liefern Herkunftsinfos"}, {"text": "Protokollierung", "correct": true, "because": "Zeichnet Änderungen auf"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenherkunft ist für Audits wichtig. b) Sie ist immer automatisch dokumentiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation nicht immer automatisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse der Datenherkunft?', 4, '[{"text": "Quellenangabe", "correct": false, "because": "Kern der Nachverfolgung"}, {"text": "Änderungsprotokolle", "correct": false, "because": "Zeigen Verlauf"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Datenherkunft nur digitale Quellen betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch physische Ursprünge möglich"}, {"text": "Ja", "correct": false, "because": "Breiterer Kontext"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Nachverfolgung?', 3, '[{"text": "Datenbank-Logs", "correct": true, "because": "Zeichnen Zugriffe auf"}, {"text": "Grafiksoftware", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Texteditor", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Datenherkunft?', 5, '[{"text": "Transparenz", "correct": true, "because": "Klarheit über Ursprung"}, {"text": "Vertrauenswürdigkeit", "correct": true, "because": "Validiert Daten"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hardware-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenherkunft hilft bei Compliance. b) Sie ist immer öffentlich einsehbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft vertraulich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Datenherkunft?', 4, '[{"text": "Metadaten", "correct": false, "because": "Liefern Kontext"}, {"text": "Dokumentation", "correct": false, "because": "Nachweis nötig"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Datenherkunft dasselbe wie die Datenquelle?', 2, '[{"text": "Nein", "correct": true, "because": "Herkunft ist Verlauf, Quelle Ursprung"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert die Datenherkunft?', 4, '[{"text": "Ursprung", "correct": true, "because": "Woher Daten stammen"}, {"text": "Änderungen", "correct": true, "because": "Verlauf nachvollziehbar"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Datenherkunft automatisch gesichert ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Muss aktiv dokumentiert werden"}, {"text": "Ja", "correct": false, "because": "Nicht immer automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenherkunft?', 3, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Klarheit über Verlauf"}, {"text": "Schnelle Erfassung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Minimale Speichergröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenherkunft unterstützt Audits. b) Sie ist nur für interne Daten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch externe Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Datenherkunft?', 5, '[{"text": "Manipulation", "correct": true, "because": "Kann verändert werden"}, {"text": "Komplexität", "correct": true, "because": "Viele Quellen möglich"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Hauptthema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nachverfolgung unwichtig?', 3, '[{"text": "Protokollierung", "correct": false, "because": "Zeigt Änderungen"}, {"text": "Zeitstempel", "correct": false, "because": "Zeigt Verlauf"}, {"text": "Monitorhelligkeit", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Datenherkunft verloren gehen?', 3, '[{"text": "Ja", "correct": true, "because": "Ohne Dokumentation möglich"}, {"text": "Nein", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenherkunft nur für Datenbanken gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien, Sensoren"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Datenherkunft?', 4, '[{"text": "Validierung", "correct": true, "because": "Bestätigt Datenverlässlichkeit"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Grafikverbesserung", "correct": false, "because": "Irrelevant"}]');
